 14	/** Private, bounded string records. Both journal and component state snapshot use the same strict reader. */
 15	internal class PrivateSettingsFile(file: File) {
 16	    private val atomic = AtomicFile(file)
 17	    fun read(): Map<String, String>? {
 18	        if (!atomic.baseFile.exists() && !File(atomic.baseFile.path + ".bak").exists()) return null
 19	        val bytes = atomic.openRead().use { input ->
 20	            val output = java.io.ByteArrayOutputStream()
 21	            val chunk = ByteArray(8192)
 22	            while (true) {
 23	                val count = input.read(chunk)
 24	                if (count < 0) break
 25	                check(output.size() + count <= MAX_BYTES)
 26	                output.write(chunk, 0, count)
 27	            }
 28	            output.toByteArray()
 29	        }
 30	        val text = Charsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT)
 31	            .onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString()
 32	        return JsonReader(StringReader(text)).use { reader ->
 33	            reader.isLenient = false
 34	            val fields = linkedMapOf<String, String>()
 35	            reader.beginObject()
 36	            while (reader.hasNext()) {
 37	                check(fields.size < 20_000)
 38	                val name = reader.nextName()
 39	                check(name.length <= 262_144 && name !in fields)
 40	                check(reader.peek() == JsonToken.STRING)
 41	                fields[name] = reader.nextString().also { check(it.length <= MAX_BYTES) }
 42	            }
 43	            reader.endObject()
 44	            check(reader.peek() == JsonToken.END_DOCUMENT)
 45	            fields
 46	        }
 47	    }
 48	    fun write(fields: Map<String, String>) {
 49	        val writer = StringWriter()
 50	        JsonWriter(writer).use { json ->
 51	            json.beginObject()
 52	            fields.forEach { (key, value) -> json.name(key).value(value) }
 53	            json.endObject()
 54	        }
 55	        val bytes = writer.toString().toByteArray(Charsets.UTF_8)
 56	        check(bytes.size <= MAX_BYTES)
 57	        val output = atomic.startWrite()
 58	        try {
 59	            output.write(bytes)
 60	            output.fd.sync()
 61	        } catch (failure: Exception) {
 62	            atomic.failWrite(output)
 63	            throw failure
 64	        }
 65	        atomic.finishWrite(output)
 66	        // AtomicFile reports some rename failures only in platform logs; require the new record to be visible.
 67	        check(read() == fields) { "Private settings record was not replaced" }
 68	    }
 69	    fun clear() {
 70	        atomic.delete()
 71	        check(!atomic.baseFile.exists() && !File(atomic.baseFile.path + ".bak").exists())
 72	    }
 73	    companion object { const val MAX_BYTES = 8 shl 20 }
 74	}
