 77	internal class AndroidImportJournal(directory: File) : ImportJournalStorage {
 78	    private val file = PrivateSettingsFile(File(directory, "settings_import_v1"))
 79	    private val internalSource = PortableSource("private.journal", "internal", 1, 0)
 80	    private val limits = DecodeLimits(maxBytes = PrivateSettingsFile.MAX_BYTES, maxEntries = 100_000,
 81	        maxStringLength = PrivateSettingsFile.MAX_BYTES)
 82	    private fun encode(configuration: SettingsConfiguration, source: PortableSource = internalSource,
 83	                       unsupported: List<UnsupportedKey> = emptyList()) =
